import "./banner.css";
import React from "react";

interface BannerProps {
  enderecoImagem: string;
  textAlternativo?: string;
}

const Banner = ({}:BannerProps) => {
  return (
    <header className="cabecalho">
      <img
        src={enderecoImagem}
        alt={textoAlternativo}
      />
    </header>
  );
};

export default Banner;
